Unpushed: `c0c25e6` + `4815c1b`. Say when to push.","timestamp":"2026-09-04T19:59:34.008Z"}],"snapshot":"c0c25e65e9448777880462d03aa6a6a701b18b8a","sources":{"docs/features/source-provenance.md":"1: # Source provenance
2: 
3: Every deploy records where the code came from, so nobody confuses what's deployed with what's on main.
4: 
5: ## CLI
6: 
7: At deploy time, if the directory is inside a git repo, capture: remote URL (origin, normalized to `https://github.com/org/repo`), branch, short and full commit SHA, and whether the working tree is dirty. Send them with the deploy.
8: 
9: Print `✓ source: github.com/acme/tools @ main a3f8e21` and, if dirty, `⚠ uncommitted changes deployed — commit before sharing`. If not a git repo, send nothing and print `source: not a git repo`.
10: 
11: ## Control plane
12: 
13: Store `repo_url`, `branch`, `commit_sha`, `dirty`, `deployed_by`, `deployed_at` on a `deploys` table — one row per deploy, so history is kept — and the latest on the app row. `GET /api/apps/<slug>/deploys` returns the history.
14: 
15: ## Repo visibility
16: 
17: Don't assume. On deploy, the control plane hits `https://api.github.com/repos/<org>/<repo>` unauthenticated; 200 means public, 404 means private or nonexistent, anything else stores unknown. Store `repo_public`. Never store a token.
18: 
19: ## Runbook
20: 
21: A line at the top, under the generated-by line: `> Deployed from github.com/acme/tools @ a3f8e21 (main).` If dirty, the line ends with `Deployed with uncommitted changes.`
22: 
23: ## Deferred (user: "do not do the web UI yet")
24: 
25: - Web UI on `/apps/<slug>`: source line under the title, commit linked to the GitHub tree at the deployed SHA (public repos), `private repo` label otherwise, Deploys tab, runbook Files table linked at the SHA.
26: - Drift: "N commits behind <branch>" from GitHub compare, public repos only, cached hourly.
27: 
28: ## Skipped
29: 
30: - GitLab — GitHub only for visibility and links. <!-- ponytail: normalize handles any host; add GitLab visibility check when a GitLab repo shows up -->
31: - Auto-deploy on push — provenance is recorded, not acted on. <!-- ponytail: needs webhooks + stored tokens; separate feature if ever -->
32: - Private-repo linking via tokens — private repos get plain SHAs, never a stored token. <!-- ponytail: deliberate; tokens in the control plane are a new threat class -->","packages/cli/lib/source.js":"1: 'use strict';
2: const { spawnSync } = require('child_process');
3: 
4: function git(args, cwd) {
5:   const r = spawnSync('git', args, { cwd, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] });
6:   return r.status === 0 ? r.stdout.trim() : null; // git missing (ENOENT) leaves status null → null
7: }
8: 
9: // git@github.com:org/repo.git | ssh://git@github.com/org/repo.git | https://github.com/org/repo.git
10: // → https://github.com/org/repo. Unrecognized shapes → null.
11: // ponytail: any host normalizes; only github gets visibility checks server-side — GitLab when asked
12: function normalizeRemote(url) {
13:   if (!url) return null;
14:   const m = url.match(/^git@([^:/]+):(.+?)(?:\.git)?\/?$/) || url.match(/^\w+:\/\/(?:[^@/]+@)?([^:/]+)\/(.+?)(?:\.git)?\/?$/);
15:   return m ? `https://${m[1]}/${m[2]}` : null;
16: }
17: 
18: // Where the deploy came from, or null when the directory is not a git repo (or git is absent).
19: function capture(dir) {
20:   if (git(['rev-parse', '--is-inside-work-tree'], dir) !== 'true') return null;
21:   const commit = git(['rev-parse', 'HEAD'], dir);
22:   if (!commit) return null; // repo with no commits yet
23:   return {
24:     repoUrl: normalizeRemote(git(['remote', 'get-url', 'origin'], dir)),
25:     branch: git(['rev-parse', '--abbrev-ref', 'HEAD'], dir), // detached HEAD reads "HEAD"
26:     commit,
27:     shortCommit: git(['rev-parse', '--short', 'HEAD'], dir) || commit.slice(0, 7),
28:     dirty: git(['status', '--porcelain'], dir) !== '',
29:   };
30: }
31: 
32: module.exports = { capture, normalizeRemote };","packages/control-plane/migrations/0003-provenance.sql":"1: -- source provenance: one deploys row per deploy, latest mirrored on the app row (matches schema.sql)
2: CREATE TABLE IF NOT EXISTS deploys (
3:   id INTEGER PRIMARY KEY,
4:   app_id INTEGER NOT NULL REFERENCES apps(id),
5:   repo_url TEXT,
6:   branch TEXT,
7:   commit_sha TEXT,
8:   dirty INTEGER,
9:   deployed_by TEXT NOT NULL,
10:   deployed_at TEXT NOT NULL DEFAULT (datetime('now'))
11: );
12: ALTER TABLE apps ADD COLUMN repo_url TEXT;
13: ALTER TABLE apps ADD COLUMN repo_branch TEXT;
14: ALTER TABLE apps ADD COLUMN repo_commit TEXT;
15: ALTER TABLE apps ADD COLUMN repo_dirty INTEGER;
16: ALTER TABLE apps ADD COLUMN repo_public INTEGER;
17: -- no deployed_at ALTER: the production DB already has it (added manually by an early
18: -- runbook experiment, alongside a dead `runbook` column) — schema.sql carries it for fresh DBs","packages/control-plane/src/index.js":"1: // small control plane: CLI API + browser auth wall + router. One Worker + D1.
2: // URLs are path-based (no custom domain): /a/<org>/<app>/... proxies to the app's Fly origin.
3: import { sign, verify, sha256, randomHex } from './token.js';
4: import { ensureFlyApp, ensureVolume, deployTokenFor, startMachine } from './fly.js';
5: import { assumeRole } from './aws.js';
6: import { runReview, generateRunbook } from './review.js';
7: import { parseCron, matches, nextRun } from './cron.js';
8: 
9: const SESSION_COOKIE = 'small_session';
10: const SESSION_TTL = 7 * 24 * 3600;
11: 
12: const orgOf = (email) => email.split('@')[1].toLowerCase().replace(/\./g, '-');
13: const now = () => Math.floor(Date.now() / 1000);
14: const json = (data, status = 200) => new Response(JSON.stringify(data), { status, headers: { 'Content-Type': 'application/json' } });
15: const html = (body, status = 200, headers = {}) =>
16:   new Response(`<!doctype html><meta name=viewport content="width=device-width,initial-scale=1"><style>body{font-family:system-ui;max-width:26rem;margin:15vh auto;padding:0 1rem}input,button{font-size:1rem;padding:.5rem}</style>${body}`, {
17:     status,
18:     headers: { 'Content-Type': 'text/html;charset=utf-8', ...headers },
19:   });
20: 
21: async function sendEmail(env, to, subject, text) {
22:   if (!env.RESEND_API_KEY) return false; // dev mode: caller falls back to echoing the code/link
23:   const resp = await fetch('https://api.resend.com/emails', {
24:     method: 'POST',
25:     headers: { Authorization: `Bearer ${env.RESEND_API_KEY}`, 'Content-Type': 'application/json' },
26:     body: JSON.stringify({ from: env.EMAIL_FROM || 'small <[REDACTED]>', to: [to], subject, text }),
27:   });
28:   return resp.ok;
29: }
30: 
31: async function cliAuth(req, env) {
32:   const m = (req.headers.get('Authorization') || '').match(/^Bearer (.+)$/);
33:   if (!m) return null;
34:   const p = await verify(m[1], env.MASTER_KEY);
35:   return p && p.t === 'cli' ? p : null;
36: }
37: 
38: async function sessionOf(req, env) {
39:   const header = req.headers.get('X-Small-Session'); // tests use the header; browsers use the cookie
40:   const cookie = (req.headers.get('Cookie') || '').match(new RegExp(`${SESSION_COOKIE}=([^;]+)`));
41:   const p = await verify(header || (cookie && cookie[1]), env.MASTER_KEY);
42:   return p && p.t === 'sess' ? p : null;
43: }
44: 
45: async function appRow(env, org, name) {
46:   return env.DB.prepare('SELECT * FROM apps WHERE org = ? AND name = ?').bind(org, name).first();
47: }
48: 
49: async function canView(env, app, email) {
50:   if (app.owner_email === email) return true;
51:   const member = await env.DB.prepare('SELECT role FROM members WHERE app_id = ? AND email = ?').bind(app.id, email).first();
52:   if (member) return true;
53:   return app.visibility === 'domain' && orgOf(email) === app.org;
54: }
55: 
56: async function canEdit(env, app, email) {
57:   if (app.owner_email === email) return true;
58:   const member = await env.DB.prepare('SELECT role FROM members WHERE app_id = ? AND email = ?').bind(app.id, email).first();
59:   return member && member.role === 'edit';
60: }
61: 
62: // ---------- CLI API ----------
63: 
64: async function apiLogin(req, env) {
65:   const { email } = await req.json();
66:   if (!email || !email.includes('@')) return json({ error: 'valid email required' }, 400);
67:   const code = String(crypto.getRandomValues(new Uint32Array(1))[0] % 1000000).padStart(6, '0');
68:   const challenge = await sign({ t: 'challenge', email, codeHash: await sha256(code), exp: now() + 600 }, env.MASTER_KEY);
69:   const sent = await sendEmail(env, email, `small login code: ${code}`, `Your small login code is ${code}\nIt expires in 10 minutes.`);
70:   if (sent) return json({ challenge });
71:   // Echoing the code is an auth bypass — only allowed on test/dev instances (marked by TEST_BYPASS_SECRET).
72:   if (!env.TEST_BYPASS_SECRET) return json({ error: 'email not configured on this control plane' }, 503);
73:   return json({ challenge, devCode: code, warning: 'test instance — code echoed' });
74: }
75: 
76: async function apiVerify(req, env) {
77:   const { challenge, code } = await req.json();
78:   const p = await verify(challenge, env.MASTER_KEY);
79:   if (!p || p.t !== 'challenge' || p.codeHash !== (await sha256(String(code)))) return json({ error: 'bad or expired code' }, 401);
80:   // ponytail: CLI tokens never expire; revoke by rotating MASTER_KEY. Add exp + refresh when it matters.
81:   const token = await sign({ t: 'cli', email: p.email, org: orgOf(p.email) }, env.MASTER_KEY);
82:   return json({ token, email: p.email, org: orgOf(p.email) });
83: }
84: 
85: // 200 = public, 404 = private or nonexistent, anything else (rate limit, outage) = unknown.
86: // Unauthenticated on purpose — never store a token; private repos just get plain SHAs.
87: // ponytail: 60 req/h unauth limit shared across CF egress IPs; null (unknown) when it trips
88: async function repoPublic(repoUrl) {
89:   const m = (repoUrl || '').match(/^https:\/\/github\.com\/([^/]+\/[^/]+)$/);
90:   if (!m) return null;
91:   try {
92:     const r = await fetch(`https://api.github.com/repos/${m[1]}`, { headers: { 'User-Agent': 'small-cp' } });
93:     return r.status === 200 ? 1 : r.status === 404 ? 0 : null;
94:   } catch {
95:     return null;
96:   }
97: }
98: 
99: async function apiDeploy(req, env, ctx, user, baseUrl) {
100:   const { name, framework, visibility, awsRoleArn, kind, review, storage, schedule, source } = await req.json();
101:   if (!name || !/^[a-z0-9-]{1,40}$/.test(name)) return json({ error: 'name must be [a-z0-9-]' }, 400);
102:   let nextAt = null;
103:   if (schedule) {
104:     if (kind !== 'job') return json({ error: 'schedule requires kind = "job" in small.toml' }, 400);
105:     try {
106:       nextAt = nextRun(parseCron(schedule), Date.now()); // also rejects "0 0 30 2 *" — valid syntax, never fires
107:     } catch (e) {
108:       return json({ error: `bad schedule "${schedule}": ${e.message} — use 5-field cron like "0 9 * * 1-5"` }, 400);
109:     }
110:   }
111:   if (storage && !(Number.isInteger(storage.sizeGb) && storage.sizeGb >= 1 && storage.sizeGb <= 100))
112:     return json({ error: 'storage.sizeGb must be an integer between 1 and 100' }, 400);
113:   if (awsRoleArn && !/^arn:aws:iam::\d{12}:role\/[\w+=,.@/-]+$/.test(awsRoleArn)) return json({ error: 'bad aws role arn' }, 400);
114:   let app = await appRow(env, user.org, name);
115:   if (app) {
116:     if (!(await canEdit(env, app, user.email))) return json({ error: `${name} exists and you cannot edit it` }, 403);
117:     if (visibility) await env.DB.prepare('UPDATE apps SET visibility = ? WHERE id = ?').bind(visibility, app.id).run();
118:     if (awsRoleArn !== undefined) await env.DB.prepare('UPDATE apps SET aws_role_arn = ? WHERE id = ?').bind(awsRoleArn || null, app.id).run();
119:     if (kind) await env.DB.prepare('UPDATE apps SET kind = ? WHERE id = ?').bind(kind === 'job' ? 'job' : 'server', app.id).run();
120:     if (schedule !== undefined) await env.DB.prepare('UPDATE apps SET schedule = ? WHERE id = ?').bind(schedule || null, app.id).run();
121:   } else {
122:     const flyApp = `small-${name}-${randomHex(3)}`;
123:     await env.DB.prepare('INSERT INTO apps (org, name, fly_app, proxy_secret, visibility, owner_email, aws_role_arn, kind, schedule) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)')
124:       .bind(user.org, name, flyApp, randomHex(32), visibility || 'domain', user.email, awsRoleArn || null, kind === 'job' ? 'job' : 'server', schedule || null)
125:       .run();
126:     app = await appRow(env, user.org, name);
127:   }
128:   if (!env.FLY_API_TOKEN) return json({ error: 'control plane has no FLY_API_TOKEN configured' }, 503);
129:   // The worker owns the Fly app lifecycle; the CLI only gets a 1h token scoped to this one app.
130:   let flyToken, volumeRegion;
131:   try {
132:     await ensureFlyApp(env, app.fly_app);
133:     if (storage) volumeRegion = await ensureVolume(env, app.fly_app, storage.sizeGb);
134:     flyToken = await deployTokenFor(env, app);
135:   } catch (e) {
136:     return json({ error: e.message }, 502);
137:   }
138:   // Source provenance: one deploys row per deploy, latest mirrored on the app row.
139:   // No source (not a git repo) clears the app-row copy — stale repo info under a fresh
140:   // deployed_at would claim the deployed code matches a commit it doesn't.
141:   const src = {
142:     repoUrl: source && source.repoUrl ? String(source.repoUrl).slice(0, 300) : null,
143:     branch: source && source.branch ? String(source.branch).slice(0, 100) : null,
144:     commit: source && /^[0-9a-f]{7,40}$/.test(source.commit || '') ? source.commit : null,
145:     dirty: source ? (source.dirty ? 1 : 0) : null,
146:   };
147:   const isPublic = src.repoUrl ? await repoPublic(src.repoUrl) : null;
148:   await env.DB.prepare(
149:     "UPDATE apps SET repo_url = ?, repo_branch = ?, repo_commit = ?, repo_dirty = ?, repo_public = ?, deployed_at = datetime('now') WHERE id = ?"
150:   ).bind(src.repoUrl, src.branch, src.commit, src.dirty, isPublic, app.id).run();
151:   await env.DB.prepare(
152:     'INSERT INTO deploys (app_id, repo_url, branch, commit_sha, dirty, deployed_by) VALUES (?, ?, ?, ?, ?, ?)'
153:   ).bind(app.id, src.repoUrl, src.branch, src.commit, src.dirty, user.email).run();
154:   // Review runs concurrently with the CLI-side Fly build; it never blocks or fails the deploy.
155:   const reviewStarted = !!(env.ANTHROPIC_API_KEY && review && review.bundle);
156:   if (reviewStarted) ctx.waitUntil(runReview(env, app.id, review.bundle, review.skipped || []));
157:   return json({
158:     flyApp: app.fly_app,
159:     proxySecret: app.proxy_secret,
160:     flyToken,
161:     url: `${baseUrl}/a/${user.org}/${name}/`,
162:     framework: framework || null,
163:     volumeRegion: volumeRegion || null,
164:     reviewStarted,
165:     reviewedAt: app.reviewed_at || null, // previous review's stamp; the CLI polls until it changes
166:     nextRun: nextAt,
167:     schedulePaused: !!app.schedule_paused,
168:   });
169: }
170: 
171: async function apiReview(req, env, user) {
172:   const name = new URL(req.url).searchParams.get('app');
173:   const app = await appRow(env, user.org, name);
174:   if (!app) return json({ error: `no app named ${name}` }, 404);
175:   if (!(await canView(env, app, user.email))) return json({ error: 'no access' }, 403);
176:   return json({
177:     review: app.review ? JSON.parse(app.review) : null,
178:     prev: app.review_prev ? JSON.parse(app.review_prev) : null,
179:     reviewedAt: app.reviewed_at || null,
180:     model: app.review_model || null,
181:   });
182: }
183: 
184: // Deploy-time review, run while the CLI holds the request open (in parallel with its Fly
185: // build). waitUntil's ~30s window is too short for the model to write review + runbook —
186: // this handler awaits the model and stores the result before responding. runReview never
187: // throws, so a model failure still answers 200 with the previous (or no) review.
188: async function apiReviewRun(req, env, user) {
189:   const { app: name, bundle, skipped } = await req.json();
190:   const app = await appRow(env, user.org, name);
191:   if (!app) return json({ error: `no app named ${name}` }, 404);
192:   if (!(await canEdit(env, app, user.email))) return json({ error: 'no access' }, 403);
