276:   if (!app) return json({ error: `no app named ${name}` }, 404);
277:   if (!(await canView(env, app, user.email))) return json({ error: 'no access' }, 403);
278:   const where = ['org = ?', 'slug = ?'];
279:   const binds = [app.org, app.name];
280:   const byUser = url.searchParams.get('user');
281:   if (byUser) { where.push('user = ?'); binds.push(byUser); }
282:   const byStatus = url.searchParams.get('status') || '';
283:   if (/^[1-5]xx$/.test(byStatus)) { where.push('status BETWEEN ? AND ?'); binds.push(+byStatus[0] * 100, +byStatus[0] * 100 + 99); }
284:   else if (/^\d+$/.test(byStatus)) { where.push('status = ?'); binds.push(+byStatus); }
285:   const after = url.searchParams.get('after');
286:   const order = after === null ? 'ORDER BY id DESC LIMIT 100' : 'ORDER BY id LIMIT 1000'; // no cursor: last 100 newest-first; cursor: ascending for --follow
287:   if (after !== null) { where.push('id > ?'); binds.push(+after); }
288:   const { results } = await env.DB.prepare(`SELECT id, ts, method, path, status, ms, user FROM request_logs WHERE ${where.join(' AND ')} ${order}`).bind(...binds).all();
289:   const cursor = results.length ? Math.max(results[0].id, results[results.length - 1].id) : +(after || 0);
290:   return json({ lines: results, cursor });
