551: 
552:   // Two crons (wrangler.jsonc): "0 3 * * *" purges request_logs, "* * * * *" runs due jobs.
553:   async scheduled(event, env, ctx) {
554:     if (event.cron === '0 3 * * *') {
555:       // 7-day request-log retention. Cutoff formatted with 'T' to match the guard's ISO timestamps.
556:       // ponytail: retention fixed at 7 days — make it a per-app column when someone needs more
557:       await env.DB.prepare("DELETE FROM request_logs WHERE ts < strftime('%Y-%m-%dT%H:%M:%S', 'now', '-7 days')").run();
558:       return;
559:     }
560:     // Every-minute tick. scheduledTime is the tick's nominal minute even when
561:     // delivery is late; last_scheduled_at pins each fired minute so a duplicate
562:     // or late tick never double-fires.
563:     // ponytail: no catch-up after downtime — a missed minute is just missed.
564:     const tick = Math.floor(event.scheduledTime / 60000) * 60; // unix seconds, floored to the minute
565:     const { results } = await env.DB.prepare(
566:       "SELECT * FROM apps WHERE kind = 'job' AND schedule IS NOT NULL AND schedule_paused = 0 AND image IS NOT NULL"
567:     ).all();
568:     for (const app of results) {
569:       let parsed;
570:       try {
571:         parsed = parseCron(app.schedule);
572:       } catch {
