574:       }
575:       if (!matches(parsed, new Date(tick * 1000)) || (app.last_scheduled_at || 0) >= tick) continue;
576:       await env.DB.prepare('UPDATE apps SET last_scheduled_at = ? WHERE id = ?').bind(tick, app.id).run();
