579:       const running = await env.DB.prepare("SELECT 1 AS x FROM runs WHERE app_id = ? AND status = 'running' LIMIT 1").bind(app.id).first();
580:       if (running) {
581:         await env.DB.prepare(
582:           "INSERT INTO runs (run_id, app_id, started_by, status, reason, finished_at) VALUES (?, ?, 'cron', 'skipped', 'previous run still active', datetime('now'))"
583:         ).bind('r-' + randomHex(6), app.id).run();
