12: const orgOf = (email) => email.split('@')[1].toLowerCase().replace(/\./g, '-');
13: const now = () => Math.floor(Date.now() / 1000);
14: const json = (data, status = 200) => new Response(JSON.stringify(data), { status, headers: { 'Content-Type': 'application/json' } });
15: const html = (body, status = 200, headers = {}) =>
16:   new Response(`<!doctype html><meta name=viewport content="width=device-width,initial-scale=1"><style>body{font-family:system-ui;max-width:26rem;margin:15vh auto;padding:0 1rem}input,button{font-size:1rem;padding:.5rem}</style>${body}`, {
17:     status,
18:     headers: { 'Content-Type': 'text/html;charset=utf-8', ...headers },
