76: async function apiVerify(req, env) {
77:   const { challenge, code } = await req.json();
78:   const p = await verify(challenge, env.MASTER_KEY);
79:   if (!p || p.t !== 'challenge' || p.codeHash !== (await sha256(String(code)))) return json({ error: 'bad or expired code' }, 401);
80:   // ponytail: CLI tokens never expire; revoke by rotating MASTER_KEY. Add exp + refresh when it matters.
81:   const token = await sign({ t: 'cli', email: p.email, org: orgOf(p.email) }, env.MASTER_KEY);
82:   return json({ token, email: p.email, org: orgOf(p.email) });
83: }
