85: // 200 = public, 404 = private or nonexistent, anything else (rate limit, outage) = unknown.
86: // Unauthenticated on purpose — never store a token; private repos just get plain SHAs.
87: // ponytail: 60 req/h unauth limit shared across CF egress IPs; null (unknown) when it trips
88: async function repoPublic(repoUrl) {
89:   const m = (repoUrl || '').match(/^https:\/\/github\.com\/([^/]+\/[^/]+)$/);
90:   if (!m) return null;
91:   try {
92:     const r = await fetch(`https://api.github.com/repos/${m[1]}`, { headers: { 'User-Agent': 'small-cp' } });
93:     return r.status === 200 ? 1 : r.status === 404 ? 0 : null;
94:   } catch {
95:     return null;
96:   }
97: }
