184: // Deploy-time review, run while the CLI holds the request open (in parallel with its Fly
185: // build). waitUntil's ~30s window is too short for the model to write review + runbook —
186: // this handler awaits the model and stores the result before responding. runReview never
187: // throws, so a model failure still answers 200 with the previous (or no) review.
188: async function apiReviewRun(req, env, user) {
189:   const { app: name, bundle, skipped } = await req.json();
190:   const app = await appRow(env, user.org, name);
191:   if (!app) return json({ error: `no app named ${name}` }, 404);
192:   if (!(await canEdit(env, app, user.email))) return json({ error: 'no access' }, 403);
193:   if (!env.ANTHROPIC_API_KEY || !bundle) return json({ error: 'review not configured' }, 503);
194:   await runReview(env, app.id, bundle, skipped || []);
195:   const fresh = await appRow(env, user.org, name);
196:   return json({
197:     review: fresh.review ? JSON.parse(fresh.review) : null,
198:     reviewedAt: fresh.reviewed_at || null,
199:     model: fresh.review_model || null,
200:   });
201: }
