203: // `small init` sends a bundle before any app row exists; the runbook comes back
204: // synchronously and the CLI writes RUNBOOK.md. Deploys store theirs via runReview.
205: async function apiRunbook(req, env) {
206:   const { bundle } = await req.json();
207:   if (!bundle) return json({ error: 'bundle required' }, 400);
208:   if (!env.ANTHROPIC_API_KEY) return json({ error: 'runbook generation not configured on this control plane' }, 503);
209:   try {
210:     return json({ runbook: await generateRunbook(env, bundle) });
211:   } catch (e) {
212:     return json({ error: e.message }, 502);
213:   }
214: }
