221:   await env.DB.prepare('INSERT INTO members (app_id, email, role) VALUES (?, ?, ?) ON CONFLICT(app_id, email) DO UPDATE SET role = excluded.role')
222:     .bind(app.id, email.toLowerCase(), role === 'edit' ? 'edit' : 'view')
223:     .run();
224:   return json({ ok: true, app: name, email: email.toLowerCase(), role: role === 'edit' ? 'edit' : 'view' });
