324: // Shared by the manual /api/runs path and the cron tick. startedBy = email or "cron".
325: // Marks the run failed and rethrows if the machine won't start.
326: async function startRun(env, app, startedBy, baseUrl) {
327:   const runId = 'r-' + randomHex(6);
328:   await env.DB.prepare('INSERT INTO runs (run_id, app_id, started_by) VALUES (?, ?, ?)').bind(runId, app.id, startedBy).run();
329:   const runToken = await sign({ t: 'run', run: runId, exp: now() + 6 * 3600 }, env.MASTER_KEY);
330:   try {
331:     await startMachine(env, app.fly_app, {
332:       image: app.image,
333:       auto_destroy: true,
334:       restart: { policy: 'no' },
335:       guest: { cpu_kind: 'shared', cpus: 1, memory_mb: 256 }, // ponytail: fixed size; read memory from small.toml when a job needs more
336:       env: {
337:         SMALL_RUN_ID: runId,
338:         SMALL_RUN_TOKEN: runToken,
339:         SMALL_USER: startedBy,
340:         SMALL_API: baseUrl,
341:         ...(startedBy === 'cron' ? { SMALL_TRIGGER: 'cron' } : {}),
342:       },
343:     });
344:   } catch (e) {
345:     await env.DB.prepare("UPDATE runs SET status = 'failed', finished_at = datetime('now') WHERE run_id = ?").bind(runId).run();
346:     throw e;
347:   }
348:   return runId;
349: }
