506: export default {
507:   async fetch(req, env, ctx) {
508:     const url = new URL(req.url);
509:     const baseUrl = `${url.protocol}//${url.host}`;
510:     const path = url.pathname;
511:     try {
512:       if (path === '/api/cli/login' && req.method === 'POST') return await apiLogin(req, env);
513:       if (path === '/api/cli/verify' && req.method === 'POST') return await apiVerify(req, env);
514:       if (path === '/api/runtime/aws-creds' && req.method === 'POST') return await apiAwsCreds(req, env);
515:       if (path.startsWith('/api/')) {
516:         const runLog = path.match(/^\/api\/runs\/([\w-]+)\/log$/);
517:         if (runLog && req.method === 'POST') return await apiRunLog(req, env, runLog[1]); // runner auth, not CLI auth
518:         const reqLog = path.match(/^\/api\/apps\/([a-z0-9-]+)\/request-log$/);
519:         if (reqLog && req.method === 'POST') return await apiRequestLogIngest(req, env, reqLog[1]); // guard auth, not CLI auth
520:         const user = await cliAuth(req, env);
521:         if (!user) return json({ error: 'run small login first' }, 401);
522:         if (path === '/api/deploy' && req.method === 'POST') return await apiDeploy(req, env, ctx, user, baseUrl);
523:         if (path === '/api/image' && req.method === 'POST') return await apiImage(req, env, user);
524:         if (path === '/api/runs' && req.method === 'POST') return await apiRunStart(req, env, user, baseUrl);
525:         if (path === '/api/runs' && req.method === 'GET') return await apiRunsList(req, env, user);
526:         const runGet = path.match(/^\/api\/runs\/([\w-]+)$/);
527:         if (runGet && req.method === 'GET') return await apiRunGet(req, env, user, runGet[1]);
528:         if (path === '/api/schedule' && req.method === 'POST') return await apiSchedulePause(req, env, user);
529:         if (path === '/api/share' && req.method === 'POST') return await apiShare(req, env, user);
530:         if (path === '/api/apps' && req.method === 'GET') return await apiApps(env, user);
531:         const deploysGet = path.match(/^\/api\/apps\/([a-z0-9-]+)\/deploys$/);
532:         if (deploysGet && req.method === 'GET') return await apiDeploys(env, user, deploysGet[1]);
533:         if (path === '/api/logs' && req.method === 'GET') return await apiLogs(req, env, user);
534:         if (path === '/api/request-logs' && req.method === 'GET') return await apiRequestLogs(req, env, user);
535:         if (path === '/api/review' && req.method === 'GET') return await apiReview(req, env, user);
536:         if (path === '/api/runbook' && req.method === 'POST') return await apiRunbook(req, env);
537:         if (path === '/api/review/run' && req.method === 'POST') return await apiReviewRun(req, env, user);
538:         return json({ error: 'no such endpoint' }, 404);
539:       }
540:       if (path === '/login') return await loginPage(req, env, baseUrl);
541:       if (path === '/auth') return await authRedirect(req, env);
542:       if (path === '/test/session' && req.method === 'POST') return await testSession(req, env);
543:       const m = path.match(/^\/a\/([a-z0-9-]+)\/([a-z0-9-]+)(\/.*)?$/);
544:       if (m) return await proxyApp(req, env, m[1], m[2], m[3] || '', baseUrl);
545:       if (path === '/') return html('<h2>small</h2><p>Deploy a Python app behind a login in one command: <code>npm i -g small-deploy</code></p>');
546:       return html('<p>Not found.</p>', 404);
547:     } catch (err) {
548:       return json({ error: `internal: ${err.message}` }, 500);
549:     }
