552:   // Two crons (wrangler.jsonc): "0 3 * * *" purges request_logs, "* * * * *" runs due jobs.
553:   async scheduled(event, env, ctx) {
554:     if (event.cron === '0 3 * * *') {
555:       // 7-day request-log retention. Cutoff formatted with 'T' to match the guard's ISO timestamps.
556:       // ponytail: retention fixed at 7 days — make it a per-app column when someone needs more
557:       await env.DB.prepare("DELETE FROM request_logs WHERE ts < strftime('%Y-%m-%dT%H:%M:%S', 'now', '-7 days')").run();
558:       return;
559:     }
560:     // Every-minute tick. scheduledTime is the tick's nominal minute even when
561:     // delivery is late; last_scheduled_at pins each fired minute so a duplicate
562:     // or late tick never double-fires.
563:     // ponytail: no catch-up after downtime — a missed minute is just missed.
564:     const tick = Math.floor(event.scheduledTime / 60000) * 60; // unix seconds, floored to the minute
565:     const { results } = await env.DB.prepare(
566:       "SELECT * FROM apps WHERE kind = 'job' AND schedule IS NOT NULL AND schedule_paused = 0 AND image IS NOT NULL"
567:     ).all();
568:     for (const app of results) {
569:       let parsed;
570:       try {
571:         parsed = parseCron(app.schedule);
572:       } catch {
573:         continue; // validated at deploy; a bad legacy row must not kill the whole tick
574:       }
575:       if (!matches(parsed, new Date(tick * 1000)) || (app.last_scheduled_at || 0) >= tick) continue;
576:       await env.DB.prepare('UPDATE apps SET last_scheduled_at = ? WHERE id = ?').bind(tick, app.id).run();
577:       // ponytail: a run whose machine died before posting an exit code stays 'running'
578:       // and blocks cron forever; add a max-age cutoff when it bites.
579:       const running = await env.DB.prepare("SELECT 1 AS x FROM runs WHERE app_id = ? AND status = 'running' LIMIT 1").bind(app.id).first();
580:       if (running) {
581:         await env.DB.prepare(
582:           "INSERT INTO runs (run_id, app_id, started_by, status, reason, finished_at) VALUES (?, ?, 'cron', 'skipped', 'previous run still active', datetime('now'))"
583:         ).bind('r-' + randomHex(6), app.id).run();
584:         continue;
585:       }
586:       try {
587:         await startRun(env, app, 'cron', env.BASE_URL);
588:       } catch (e) {
589:         console.error(`cron: ${app.org}/${app.name}: ${e.message}`); // run row already marked failed
590:       }
591:     }
592:   },
593: };"}},"label":"answer-2","response":{"answer":"The feature's stated purpose is provenance: the CLI captures the exact commit and working-tree dirty state at deploy time "so nobody confuses what's deployed with what's on main" (docs/features/source-provenance.md:3). Main can move or diverge from what was actually built and shipped, so recording the branch alone wouldn't tell you what code is actually running. The commit SHA (full + short) pins the exact code state, and the dirty flag flags when uncommitted local changes were included, which the CLI surfaces as a warning ('⚠ uncommitted changes deployed — commit before sharing', doc line 9) and mirrors into the runbook header. Design decision d7 also records that history matters — one row per deploy in a `deploys` table plus the latest mirrored on the app row — again because 'what's on main' at deploy time isn't necessarily durable/traceable later; only the commit SHA is a fixed, checkable reference. This is captured in packages/cli/lib/source.js (commit, shortCommit, dirty fields) and stored via packages/control-plane/src/index.js's apiDeploy (lines 141-153). No rationale is recorded for omitting a 'show main branch' alternative — the docs simply don't mention it as considered.","citations":[{"end_line":9,"kind":"code","path":"docs/features/source-provenance.md","start_line":1},{"decision_id":"d7","kind":"decision"},{"end_line":30,"kind":"code","path":"packages/cli/lib/source.js","start_line":18},{"end_line":153,"kind":"code","path":"packages/control-plane/src/index.js","start_line":138}]}},{"available_context":{"snapshot":"c0c25e65e9448777880462d03aa6a6a701b18b8a","sources":{"docs/features/source-provenance.md":"1: # Source provenance
2: 
3: Every deploy records where the code came from, so nobody confuses what's deployed with what's on main.
4: 
5: ## CLI
6: 
7: At deploy time, if the directory is inside a git repo, capture: remote URL (origin, normalized to `https://github.com/org/repo`), branch, short and full commit SHA, and whether the working tree is dirty. Send them with the deploy.
8: 
9: Print `✓ source: github.com/acme/tools @ main a3f8e21` and, if dirty, `⚠ uncommitted changes deployed — commit before sharing`. If not a git repo, send nothing and print `source: not a git repo`.
10: 
11: ## Control plane
12: 
13: Store `repo_url`, `branch`, `commit_sha`, `dirty`, `deployed_by`, `deployed_at` on a `deploys` table — one row per deploy, so history is kept — and the latest on the app row. `GET /api/apps/<slug>/deploys` returns the history.
14: 
15: ## Repo visibility
16: 
17: Don't assume. On deploy, the control plane hits `https://api.github.com/repos/<org>/<repo>` unauthenticated; 200 means public, 404 means private or nonexistent, anything else stores unknown. Store `repo_public`. Never store a token.
18: 
19: ## Runbook
20: 
21: A line at the top, under the generated-by line: `> Deployed from github.com/acme/tools @ a3f8e21 (main).` If dirty, the line ends with `Deployed with uncommitted changes.`
22: 
23: ## Deferred (user: "do not do the web UI yet")
24: 
25: - Web UI on `/apps/<slug>`: source line under the title, commit linked to the GitHub tree at the deployed SHA (public repos), `private repo` label otherwise, Deploys tab, runbook Files table linked at the SHA.
26: - Drift: "N commits behind <branch>" from GitHub compare, public repos only, cached hourly.
27: 
28: ## Skipped
29: 
30: - GitLab — GitHub only for visibility and links. <!-- ponytail: normalize handles any host; add GitLab visibility check when a GitLab repo shows up -->
31: - Auto-deploy on push — provenance is recorded, not acted on. <!-- ponytail: needs webhooks + stored tokens; separate feature if ever -->
32: - Private-repo linking via tokens — private repos get plain SHAs, never a stored token. <!-- ponytail: deliberate; tokens in the control plane are a new threat class -->","packages/cli/lib/source.js":"1: 'use strict';
2: const { spawnSync } = require('child_process');
3: 
4: function git(args, cwd) {
5:   const r = spawnSync('git', args, { cwd, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] });
6:   return r.status === 0 ? r.stdout.trim() : null; // git missing (ENOENT) leaves status null → null
7: }
8: 
9: // git@github.com:org/repo.git | ssh://git@github.com/org/repo.git | https://github.com/org/repo.git
10: // → https://github.com/org/repo. Unrecognized shapes → null.
11: // ponytail: any host normalizes; only github gets visibility checks server-side — GitLab when asked
12: function normalizeRemote(url) {
13:   if (!url) return null;
14:   const m = url.match(/^git@([^:/]+):(.+?)(?:\.git)?\/?$/) || url.match(/^\w+:\/\/(?:[^@/]+@)?([^:/]+)\/(.+?)(?:\.git)?\/?$/);
15:   return m ? `https://${m[1]}/${m[2]}` : null;
16: }
17: 
18: // Where the deploy came from, or null when the directory is not a git repo (or git is absent).
19: function capture(dir) {
20:   if (git(['rev-parse', '--is-inside-work-tree'], dir) !== 'true') return null;
21:   const commit = git(['rev-parse', 'HEAD'], dir);
22:   if (!commit) return null; // repo with no commits yet
23:   return {
24:     repoUrl: normalizeRemote(git(['remote', 'get-url', 'origin'], dir)),
25:     branch: git(['rev-parse', '--abbrev-ref', 'HEAD'], dir), // detached HEAD reads "HEAD"
26:     commit,
27:     shortCommit: git(['rev-parse', '--short', 'HEAD'], dir) || commit.slice(0, 7),
28:     dirty: git(['status', '--porcelain'], dir) !== '',
29:   };
30: }
