404: // Called by runner.py with the per-run token — not a CLI token.
405: async function apiRunLog(req, env, runId) {
406:   const m = (req.headers.get('Authorization') || '').match(/^Bearer (.+)$/);
407:   const p = m && (await verify(m[1], env.MASTER_KEY));
408:   if (!p || p.t !== 'run' || p.run !== runId) return json({ error: 'bad run token' }, 401);
409:   const { lines = [], exitCode } = await req.json();
410:   if (lines.length) {
411:     // ponytail: MAX(seq) is race-free only because one runner posts batches sequentially
412:     const { m: maxSeq } = await env.DB.prepare('SELECT COALESCE(MAX(seq), -1) AS m FROM run_logs WHERE run_id = ?').bind(runId).first();
413:     let seq = maxSeq;
414:     const stmt = env.DB.prepare('INSERT INTO run_logs (run_id, seq, line) VALUES (?, ?, ?)');
415:     await env.DB.batch(lines.map((l) => stmt.bind(runId, ++seq, String(l))));
416:   }
417:   if (exitCode !== undefined && exitCode !== null) {
418:     await env.DB.prepare("UPDATE runs SET status = ?, exit_code = ?, finished_at = datetime('now') WHERE run_id = ?")
419:       .bind(exitCode === 0 ? 'finished' : 'failed', exitCode, runId)
420:       .run();
421:   }
422:   return json({ ok: true });
423: }
