467: async function proxyApp(req, env, org, name, rest, baseUrl) {
468:   const sess = await sessionOf(req, env);
469:   const prefix = `/a/${org}/${name}`;
470:   if (!sess) {
471:     if (req.method !== 'GET') return json({ error: 'login required' }, 401);
472:     return new Response(null, { status: 302, headers: { Location: `${baseUrl}/login?next=${encodeURIComponent(prefix + '/')}` } });
473:   }
474:   const app = await appRow(env, org, name);
475:   if (!app) return html(`<p>No app <b>${name}</b> here.</p>`, 404);
476:   if (!(await canView(env, app, sess.email))) return html(`<p><b>${sess.email}</b> does not have access to <b>${name}</b>. Ask the owner to run <code>small share ${sess.email}</code>.</p>`, 403);
477:   if (rest === '') return new Response(null, { status: 301, headers: { Location: `${prefix}/` } }); // relative URLs need the trailing slash
478: 
479:   const origin = `https://${app.fly_app}.fly.dev`;
480:   const target = new URL(req.url);
481:   const headers = new Headers(req.headers);
482:   headers.delete('Cookie'); // the app never sees the session
483:   headers.delete('X-Small-Session');
484:   headers.set('X-Small-User', sess.email);
485:   headers.set('X-Small-Org', org);
486:   headers.set('X-Small-Proxy', app.proxy_secret);
487:   let resp;
488:   for (let attempt = 0; ; attempt++) {
489:     resp = await fetch(`${origin}${rest}${target.search}`, {
490:       method: req.method,
491:       headers,
492:       body: ['GET', 'HEAD'].includes(req.method) ? undefined : req.body,
493:       redirect: 'manual',
494:     });
495:     // Fly answers 502/503 while a scaled-to-zero machine wakes (~30s for torch-heavy apps);
496:     // hold safe-to-repeat requests instead of showing the browser a Bad Gateway.
497:     if (![502, 503].includes(resp.status) || !['GET', 'HEAD'].includes(req.method) || attempt >= 9) break;
498:     await new Promise((r) => setTimeout(r, 5000));
499:   }
500:   const out = new Headers(resp.headers);
501:   const loc = out.get('Location');
502:   if (loc && loc.startsWith('/') && !loc.startsWith('/a/')) out.set('Location', prefix + loc); // path-based hosting: re-prefix app redirects
503:   return new Response(resp.body, { status: resp.status, headers: out });
504: }
