4: function git(args, cwd) {
5:   const r = spawnSync('git', args, { cwd, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] });
6:   return r.status === 0 ? r.stdout.trim() : null; // git missing (ENOENT) leaves status null → null
7: }
8: 
9: // git@github.com:org/repo.git | ssh://git@github.com/org/repo.git | https://github.com/org/repo.git
10: // → https://github.com/org/repo. Unrecognized shapes → null.
11: // ponytail: any host normalizes; only github gets visibility checks server-side — GitLab when asked
12: function normalizeRemote(url) {
13:   if (!url) return null;
14:   const m = url.match(/^git@([^:/]+):(.+?)(?:\.git)?\/?$/) || url.match(/^\w+:\/\/(?:[^@/]+@)?([^:/]+)\/(.+?)(?:\.git)?\/?$/);
15:   return m ? `https://${m[1]}/${m[2]}` : null;
16: }
17: 
18: // Where the deploy came from, or null when the directory is not a git repo (or git is absent).
19: function capture(dir) {
20:   if (git(['rev-parse', '--is-inside-work-tree'], dir) !== 'true') return null;
21:   const commit = git(['rev-parse', 'HEAD'], dir);
22:   if (!commit) return null; // repo with no commits yet
23:   return {
24:     repoUrl: normalizeRemote(git(['remote', 'get-url', 'origin'], dir)),
25:     branch: git(['rev-parse', '--abbrev-ref', 'HEAD'], dir), // detached HEAD reads "HEAD"
26:     commit,
27:     shortCommit: git(['rev-parse', '--short', 'HEAD'], dir) || commit.slice(0, 7),
28:     dirty: git(['status', '--porcelain'], dir) !== '',
29:   };
30: }
