99: async function apiDeploy(req, env, ctx, user, baseUrl) {
100:   const { name, framework, visibility, awsRoleArn, kind, review, storage, schedule, source } = await req.json();
101:   if (!name || !/^[a-z0-9-]{1,40}$/.test(name)) return json({ error: 'name must be [a-z0-9-]' }, 400);
102:   let nextAt = null;
103:   if (schedule) {
104:     if (kind !== 'job') return json({ error: 'schedule requires kind = "job" in small.toml' }, 400);
105:     try {
106:       nextAt = nextRun(parseCron(schedule), Date.now()); // also rejects "0 0 30 2 *" — valid syntax, never fires
107:     } catch (e) {
108:       return json({ error: `bad schedule "${schedule}": ${e.message} — use 5-field cron like "0 9 * * 1-5"` }, 400);
109:     }
110:   }
111:   if (storage && !(Number.isInteger(storage.sizeGb) && storage.sizeGb >= 1 && storage.sizeGb <= 100))
112:     return json({ error: 'storage.sizeGb must be an integer between 1 and 100' }, 400);
113:   if (awsRoleArn && !/^arn:aws:iam::\d{12}:role\/[\w+=,.@/-]+$/.test(awsRoleArn)) return json({ error: 'bad aws role arn' }, 400);
114:   let app = await appRow(env, user.org, name);
115:   if (app) {
116:     if (!(await canEdit(env, app, user.email))) return json({ error: `${name} exists and you cannot edit it` }, 403);
117:     if (visibility) await env.DB.prepare('UPDATE apps SET visibility = ? WHERE id = ?').bind(visibility, app.id).run();
118:     if (awsRoleArn !== undefined) await env.DB.prepare('UPDATE apps SET aws_role_arn = ? WHERE id = ?').bind(awsRoleArn || null, app.id).run();
119:     if (kind) await env.DB.prepare('UPDATE apps SET kind = ? WHERE id = ?').bind(kind === 'job' ? 'job' : 'server', app.id).run();
120:     if (schedule !== undefined) await env.DB.prepare('UPDATE apps SET schedule = ? WHERE id = ?').bind(schedule || null, app.id).run();
121:   } else {
122:     const flyApp = `small-${name}-${randomHex(3)}`;
123:     await env.DB.prepare('INSERT INTO apps (org, name, fly_app, proxy_secret, visibility, owner_email, aws_role_arn, kind, schedule) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)')
124:       .bind(user.org, name, flyApp, randomHex(32), visibility || 'domain', user.email, awsRoleArn || null, kind === 'job' ? 'job' : 'server', schedule || null)
125:       .run();
126:     app = await appRow(env, user.org, name);
127:   }
128:   if (!env.FLY_API_TOKEN) return json({ error: 'control plane has no FLY_API_TOKEN configured' }, 503);
129:   // The worker owns the Fly app lifecycle; the CLI only gets a 1h token scoped to this one app.
130:   let flyToken, volumeRegion;
131:   try {
132:     await ensureFlyApp(env, app.fly_app);
133:     if (storage) volumeRegion = await ensureVolume(env, app.fly_app, storage.sizeGb);
134:     flyToken = await deployTokenFor(env, app);
135:   } catch (e) {
136:     return json({ error: e.message }, 502);
137:   }
138:   // Source provenance: one deploys row per deploy, latest mirrored on the app row.
139:   // No source (not a git repo) clears the app-row copy — stale repo info under a fresh
140:   // deployed_at would claim the deployed code matches a commit it doesn't.
141:   const src = {
142:     repoUrl: source && source.repoUrl ? String(source.repoUrl).slice(0, 300) : null,
143:     branch: source && source.branch ? String(source.branch).slice(0, 100) : null,
144:     commit: source && /^[0-9a-f]{7,40}$/.test(source.commit || '') ? source.commit : null,
145:     dirty: source ? (source.dirty ? 1 : 0) : null,
146:   };
147:   const isPublic = src.repoUrl ? await repoPublic(src.repoUrl) : null;
148:   await env.DB.prepare(
149:     "UPDATE apps SET repo_url = ?, repo_branch = ?, repo_commit = ?, repo_dirty = ?, repo_public = ?, deployed_at = datetime('now') WHERE id = ?"
150:   ).bind(src.repoUrl, src.branch, src.commit, src.dirty, isPublic, app.id).run();
151:   await env.DB.prepare(
152:     'INSERT INTO deploys (app_id, repo_url, branch, commit_sha, dirty, deployed_by) VALUES (?, ?, ?, ?, ?, ?)'
153:   ).bind(app.id, src.repoUrl, src.branch, src.commit, src.dirty, user.email).run();
154:   // Review runs concurrently with the CLI-side Fly build; it never blocks or fails the deploy.
155:   const reviewStarted = !!(env.ANTHROPIC_API_KEY && review && review.bundle);
156:   if (reviewStarted) ctx.waitUntil(runReview(env, app.id, review.bundle, review.skipped || []));
157:   return json({
158:     flyApp: app.fly_app,
159:     proxySecret: app.proxy_secret,
160:     flyToken,
161:     url: `${baseUrl}/a/${user.org}/${name}/`,
162:     framework: framework || null,
163:     volumeRegion: volumeRegion || null,
164:     reviewStarted,
165:     reviewedAt: app.reviewed_at || null, // previous review's stamp; the CLI polls until it changes
166:     nextRun: nextAt,
167:     schedulePaused: !!app.schedule_paused,
168:   });
169: }
